-- Shah Rukh Khan (Born: 1965-11-02)
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `website`, `social_links`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`)
VALUES ('Shah Rukh Khan', 'SRK', 'shah-rukh-khan', 'Male', 'Acting', '1965-11-02', NULL, 'New Delhi, India', 'Shah Rukh Khan (born 2 November 1965), often referred to by the acronym SRK and popularly known as the \"Baadshah of Bollywood\" and \"King Khan\", is an Indian actor, film producer, and television personality. One of the most famous and successful cinematic figures in the world, Khan has appeared in over 90 films and earned numerous accolades, including 14 Filmfare Awards and the Padma Shri. His historic blockbusters include Dilwale Dulhania Le Jayenge, Kuch Kuch Hota Hai, Devdas, Swades, Chak De! India, My Name Is Khan, and his historic 2023 box office triumphs Pathaan, Jawan, and Dunki.', 'people/photos/shah-rukh-khan.jpg', 'https://twitter.com/iamsrk', '{\"instagram\":\"https:\\/\\/www.instagram.com\\/iamsrk\",\"twitter\":\"https:\\/\\/twitter.com\\/iamsrk\",\"imdb\":\"https:\\/\\/www.imdb.com\\/name\\/nm0451321\\/\"}', 1, 'active', 1, @now, @now)
