VALUES ('David Schwimmer', 'David Schwimmer', 'david-schwimmer', 'Male', 'Acting', '1966-11-02', NULL, 'Flushing, Queens, New York City, USA', 'David Lawrence Schwimmer (born November 2, 1966) is an American actor, director, and producer. He achieved global stardom playing the paleontologist Ross Geller in the legendary NBC sitcom Friends (1994–2004), for which he received a Primetime Emmy Award nomination. He starred as Captain Herbert Sobel in Steven Spielberg\'s acclaimed miniseries Band of Brothers (2001) and earned a second Emmy nomination portraying lawyer Robert Kardashian in The People v. O. J. Simpson: American Crime Story (2016). He famously voiced Melman the Giraffe in DreamWorks\' animated franchise Madagascar.', 'people/photos/david-schwimmer.jpg', 'https://www.instagram.com/_davidschwimmer_', '{\"instagram\":\"https:\\/\\/www.instagram.com\\/_davidschwimmer_\",\"twitter\":\"https:\\/\\/twitter.com\\/davidschwimmer\",\"imdb\":\"https:\\/\\/www.imdb.com\\/name\\/nm0001710\\/\"}', 1, 'active', 1, @now, @now)
