-- Esha Deol (Born: 1981-11-02)
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `website`, `social_links`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`)
VALUES ('Esha Deol', 'Esha Deol', 'esha-deol', 'Female', 'Acting', '1981-11-02', NULL, 'Mumbai, Maharashtra, India', 'Esha Deol Takhtani (born 2 November 1981) is an Indian actress who works predominantly in Hindi cinema. Born to legendary actors Dharmendra and Hema Malini, Deol made her debut in Koi Mere Dil Se Poochhe (2002), which earned her the Filmfare Award for Best Female Debut. She gained mainstream acclaim and commercial stardom starring as Sheena in Yash Raj Films\' action blockbuster Dhoom (2004), Mani Ratnam\'s political drama Yuva (2004), the hit comedy No Entry (2005), and starred alongside Ajay Devgn in the Disney+ Hotstar crime thriller series Rudra: The Edge of Darkness (2022).', 'people/photos/esha-deol.jpg', 'https://www.instagram.com/imeshadeol', '{\"instagram\":\"https:\\/\\/www.instagram.com\\/imeshadeol\",\"twitter\":\"https:\\/\\/twitter.com\\/Esha_Deol\",\"imdb\":\"https:\\/\\/www.imdb.com\\/name\\/nm1110057\\/\"}', 1, 'active', 1, @now, @now)
