VALUES ('Anu Malik', 'Anu Malik', 'anu-malik', 'Male', 'Sound', '1960-11-02', NULL, 'Mumbai, Maharashtra, India', 'Anwar Sardar Malik (born 2 November 1960), known professionally as Anu Malik, is a National Award-winning Indian music director, composer, and singer. Son of veteran composer Sardar Malik, he is one of Bollywood\'s most iconic and prolific music maestros, having composed for over 350 films. He won the National Film Award for Best Music Direction for J. P. Dutta\'s Refugee (2000) and two Filmfare Awards for Best Music Director for the blockbuster soundtracks of Baazigar (1993) and Main Hoon Na (2004). He is also celebrated for Border, Judwaa, Asoka, Josh, and serving as a beloved judge on Indian Idol for over a decade.', 'people/photos/anu-malik.jpg', 'https://www.instagram.com/anumalikmusic', '{\"instagram\":\"https:\\/\\/www.instagram.com\\/anumalikmusic\",\"imdb\":\"https:\\/\\/www.imdb.com\\/name\\/nm0540417\\/\"}', 1, 'active', 1, @now, @now)
