VALUES ('Karamo Brown', 'Karamo Brown', 'karamo-brown', 'Male', 'Acting', '1980-11-02', NULL, 'Houston, Texas, USA', 'Karamo Karega Brown (born November 2, 1980) is an American television host, reality television personality, author, and activist. He gained international fame and widespread affection as the Culture expert on Netflix\'s multiple Emmy Award-winning makeover series Queer Eye (2018–present). In 2022, he launched his own nationally syndicated daytime talk show, Karamo. Brown also competed on Season 28 of Dancing with the Stars and is a prominent public advocate for youth mental health and LGBTQ+ rights.', 'people/photos/karamo-brown.jpg', 'https://www.instagram.com/karamo', '{\"instagram\":\"https:\\/\\/www.instagram.com\\/karamo\",\"twitter\":\"https:\\/\\/twitter.com\\/Karamo\",\"imdb\":\"https:\\/\\/www.imdb.com\\/name\\/nm1711200\\/\"}', 1, 'active', 1, @now, @now)
