-- k.d. lang (Born: 1961-11-02)
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `website`, `social_links`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`)
VALUES ('k.d. lang', 'k.d. lang', 'kd-lang', 'Female', 'Sound', '1961-11-02', NULL, 'Consort, Alberta, Canada', 'Kathryn Dawn Lang (born November 2, 1961), known by her stylized stage name k.d. lang, is a celebrated Canadian pop and country singer-songwriter and actress. A legendary vocalist celebrated for her rich mezzo-soprano tone, lang has won four Grammy Awards and eight Juno Awards. Her signature international breakthrough hit \"Constant Craving\" (1992) from her multi-platinum album Ingénue became a timeless global classic. An inductee into the Canadian Music Hall of Fame, she has also contributed acclaimed songs to movie soundtracks and performed at the 2010 Winter Olympics opening ceremony.', 'people/photos/kd-lang.jpg', 'https://www.kdlang.com', '{\"instagram\":\"https:\\/\\/www.instagram.com\\/kdlang\",\"twitter\":\"https:\\/\\/twitter.com\\/kdlang\",\"imdb\":\"https:\\/\\/www.imdb.com\\/name\\/nm0005121\\/\"}', 1, 'active', 1, @now, @now)
