VALUES ('Kendall Jenner', 'Kendall Jenner', 'kendall-jenner', 'Female', 'Modeling', '1995-11-03', NULL, 'Los Angeles, California, USA', 'Kendall Nicole Jenner (born November 3, 1995) is an American supermodel, media personality, and businesswoman. Rising to fame on the reality television phenomenon Keeping Up with the Kardashians (2007–2021) and Hulu\'s The Kardashians, Jenner launched a sensational high-fashion runway career, becoming the highest-paid model in the world according to Forbes. She has walked for Chanel, Versace, Fendi, Marc Jacobs, and Victoria\'s Secret, while founding the successful premium tequila brand 818 Tequila.', 'people/photos/kendall-jenner.jpg', 'https://www.instagram.com/kendalljenner', '{\"instagram\":\"https:\\/\\/www.instagram.com\\/kendalljenner\",\"twitter\":\"https:\\/\\/twitter.com\\/KendallJenner\",\"imdb\":\"https:\\/\\/www.imdb.com\\/name\\/nm2835957\\/\"}', 1, 'active', 1, @now, @now)
