-- Saumya Tandon (Born: 1984-11-03)
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `website`, `social_links`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`)
VALUES ('Saumya Tandon', 'Saumya Tandon', 'saumya-tandon', 'Female', 'Acting', '1984-11-03', NULL, 'Bhopal, Madhya Pradesh, India', 'Saumya Tandon (born 3 November 1984) is an Indian television actress and television host. She gained massive household recognition for playing the sophisticated and charming character Anita Vibhuti Narayan Mishra (Anita Bhabhi / Gori Mem) in the hit sitcom Bhabiji Ghar Par Hain! (2015–2020). In Bollywood, she famously portrayed Kareena Kapoor\'s sister Roop in Imtiaz Ali\'s romantic comedy classic Jab We Met (2007). She is also an acclaimed television anchor who co-hosted Dance India Dance with Jay Bhanushali for multiple seasons and hosted Bournvita Quiz Contest with Derek O\'Brien.', 'people/photos/saumya-tandon.jpg', 'https://www.instagram.com/saumyas_world_', '{\"instagram\":\"https:\\/\\/www.instagram.com\\/saumyas_world_\",\"twitter\":\"https:\\/\\/twitter.com\\/saumyatandon\",\"imdb\":\"https:\\/\\/www.imdb.com\\/name\\/nm2835266\\/\"}', 1, 'active', 1, @now, @now)
