-- Prithviraj Kapoor (Born: 1906-11-03)
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `website`, `social_links`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`)
VALUES ('Prithviraj Kapoor', 'Prithviraj Kapoor', 'prithviraj-kapoor', 'Male', 'Acting', '1906-11-03', '1972-05-29', 'Samundri, Punjab, British India', 'Prithviraj Kapoor (3 November 1906 – 29 May 1972) was a legendary pioneer of Indian cinema and theatre, and the founding patriarch of the iconic Kapoor family of Hindi cinema. A founding member of the Indian People\'s Theatre Association (IPTA) and founder of Prithvi Theatres in 1944, Kapoor is immortalized for his towering, authoritative performance as Mughal Emperor Akbar in K. Asif\'s epic masterpiece Mughal-e-Azam (1960). His other classic works include Alam Ara (India\'s first sound film, 1931), Sikandar (1941), and Raj Kapoor\'s Awaara (1951). He was posthumously awarded the Dadasaheb Phalke Award in 1971.', 'people/photos/prithviraj-kapoor.jpg', 'https://en.wikipedia.org/wiki/Prithviraj_Kapoor', '{\"imdb\":\"https:\\/\\/www.imdb.com\\/name\\/nm0438491\\/\"}', 1, 'active', 1, @now, @now)
