-- Kate Capshaw (Born: 1953-11-03)
INSERT INTO `people` (`name`, `stage_name`, `slug`, `gender`, `known_for_department`, `birth_date`, `death_date`, `birth_place`, `biography`, `photo_path`, `website`, `social_links`, `is_featured`, `status`, `is_active`, `created_at`, `updated_at`)
VALUES ('Kate Capshaw', 'Kate Capshaw', 'kate-capshaw', 'Female', 'Acting', '1953-11-03', NULL, 'Fort Worth, Texas, USA', 'Kathleen Sue Spielberg (née Nail, born November 3, 1953), known professionally as Kate Capshaw, is an American actress, painter, and producer. She rose to international cinematic fame starring as the glamorous singer Willie Scott opposite Harrison Ford in Steven Spielberg\'s iconic action-adventure blockbuster Indiana Jones and the Temple of Doom (1984). Capshaw also starred in the hit sci-fi adventure SpaceCamp (1986), the neo-noir thriller Dreamscape (1984), Black Rain (1989), Just Cause (1995) with Sean Connery, and The Love Letter (1999).', 'people/photos/kate-capshaw.jpg', 'https://www.imdb.com/name/nm0000324/', '{\"imdb\":\"https:\\/\\/www.imdb.com\\/name\\/nm0000324\\/\"}', 1, 'active', 1, @now, @now)
